use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},collections::BTreeMap,fmt::Write,process::{Command,Stdio}};
const R:&str="/home/ubuntu/src/zopro-perf-work/key-point-orbits176";const OUT:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-06-key-point-orbits176";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn walk(p:&Path)->Vec<PathBuf>{let mut v=vec![];for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){v.extend(walk(&p));}else{v.push(p);}}v.sort();v}
fn gzip(p:&Path,b:&[u8]){let tmp=p.with_extension("tmp");fs::write(&tmp,b).unwrap();assert!(Command::new("gzip").args(["-n","-c"]).arg(&tmp).stdout(Stdio::from(fs::File::create(p).unwrap())).status().unwrap().success());let check=Command::new("gzip").args(["-d","-c"]).arg(p).output().unwrap();assert!(check.status.success());assert_eq!(check.stdout,b);fs::remove_file(tmp).unwrap();}
fn main(){let review=read(r("review.json"));assert_eq!(review["passed"],true);assert_eq!(review["additional_phi_alias_excess"],0);let out=Path::new(OUT);assert!(!out.exists());fs::create_dir_all(out.join("artifacts")).unwrap();
 let allowed=|p:&Path|matches!(p.extension().and_then(|s|s.to_str()),Some("rs"|"md"|"json"|"log"));let mut files=vec![];for e in fs::read_dir(R).unwrap(){let p=e.unwrap().path();if p.is_file()&&allowed(&p){files.push(p);}}for d in["runs","initial-compile-inference","initial-compile-bitcode"]{files.extend(walk(&r(d)).into_iter().filter(|p|allowed(p)));}let mut archive=BTreeMap::new();for p in files{let b=fs::read(&p).unwrap();let utf8=String::from_utf8(b.clone()).unwrap();assert_eq!(utf8.as_bytes(),b);archive.insert(p.display().to_string(),json!({"utf8":utf8,"length":b.len(),"sha256":hash(&b)}));}let count=archive.len();gzip(&out.join("artifacts/receipts-and-helpers.json.gz"),&serde_json::to_vec(&archive).unwrap());
 for n in["analysis.json","review.json","inputs.json","pins.json","plan.json","design.md","codec.rs","census.rs","review.rs","prepare.rs","repair-link.rs","publish.rs"]{fs::copy(r(n),out.join("artifacts").join(n)).unwrap();}
 fs::copy(r("report-draft.md"),out.join("README.md")).unwrap();let mut sums=String::new();let files=walk(out);for p in&files{writeln!(sums,"{}  {}",hash(&fs::read(p).unwrap()),p.strip_prefix(out).unwrap().display()).unwrap();}fs::write(out.join("SHA256SUMS"),sums).unwrap();println!("Published{}files/{count}exactUTF8members;allarchivebyteschecked;no point/scalar/key payloads or executables.",files.len()+1);}
